package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.RecoveryPlanning.World;
import static net.battlespades.bot.BotVectors.*;

/** Mode-sanctioned horde target allocation, time estimates and bounded progress watchdogs. */
public final class HordeCoordinator {
    public record Member(int playerId,Vector position,boolean bot,boolean canDig,boolean canBuild,boolean working){}
    public record Target(int playerId,Vector position){}
    public record Siege(boolean isolated,int floorZ,StructureCollapse.Plan plan,double analysedAt,StructureCollapse.Approach approach,Vector position){}
    public record Order(int zombieId,int targetId,String role,Vector goal,List<Cell> cells,Cell aim,int stuckLevel){public Order{cells=List.copyOf(cells);}public int roleCode(){return switch(role){case "hunt"->0;case "flank"->1;case "dig_root"->2;case "climb"->3;case "surround"->4;case "tunnel"->5;default->throw new IllegalStateException("Unknown horde role");};}}
    public record Metrics(int stuckEvents,int tunnelOrders,int digOrders,int surroundOrders,int climbOrders,int maxPile,Map<Integer,Integer> piles,int collapseChoices,int breachChoices){public Metrics{piles=Map.copyOf(piles);}}
    private static final class Progress{List<Object> key;double best,at;int level;double levelSince;Vector anchor;double closedAt;Progress(List<Object> key,double best,double now,int level,Vector anchor){this.key=key;this.best=best;at=now;this.level=level;levelSince=now;this.anchor=anchor;closedAt=now;}}
    private record Role(int target,String role){}private record Breach(Vector position,List<Cell> cells){}private record BreachCache(double at,int target,List<Integer> column,Breach decision){}private record Via(double at,StructureCollapse.Approach approach,ProjectSites.Column column,Vector point,Cell entry){}
    private final Thread owner=Thread.currentThread();private final LinkedHashMap<Integer,Integer> targets=new LinkedHashMap<>();private final Map<Integer,Progress> progress=new HashMap<>();private final Map<Integer,Boolean> besieged=new HashMap<>();private final Map<Integer,Role> roles=new HashMap<>();private final Map<Integer,BreachCache> breaches=new HashMap<>();private final Map<Integer,Via> vias=new HashMap<>();private final Map<Integer,Integer> stuck=new HashMap<>(),piles=new LinkedHashMap<>();private int stuckEvents,tunnelOrders,digOrders,surroundOrders,climbOrders,maxPile,collapseChoices,breachChoices;
    void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Horde coordination outside owner");}
    public void reset(){owned();targets.clear();progress.clear();besieged.clear();roles.clear();breaches.clear();vias.clear();stuck.clear();piles.clear();stuckEvents=tunnelOrders=digOrders=surroundOrders=climbOrders=maxPile=collapseChoices=breachChoices=0;}
    public boolean struggling(int id){owned();return stuck.getOrDefault(id,0)>0;}public Metrics metrics(){owned();return new Metrics(stuckEvents,tunnelOrders,digOrders,surroundOrders,climbOrders,maxPile,piles,collapseChoices,breachChoices);}
    static int floor(Vector p){return (int)Math.rint(p.z()+2.25);}static Vector ring(Vector center,int slot,int slots,double radius,int floor,double phase){double angle=phase+Math.TAU*Math.floorMod(slot,Math.max(1,slots))/Math.max(1,slots);return new Vector(center.x()+radius*Math.cos(angle),center.y()+radius*Math.sin(angle),floor-2.25);}
    public static Vector standNear(World w,Vector p,int floor,int span){if(w==null)return p;int x=(int)Math.floor(p.x()),y=(int)Math.floor(p.y());if(x<0||x>=512||y<0||y>=512)return null;var offsets=new ArrayList<Integer>();for(int i=-span;i<=span;i++)offsets.add(i);offsets.sort(Comparator.comparingInt(Math::abs));for(int offset:offsets){int z=floor+offset;if(z>=2&&z<239&&w.solid(x,y,z)&&!w.solid(x,y,z-1)&&!w.solid(x,y,z-2))return new Vector(x+.5,y+.5,z-2.25);}return null;}
    public static int pileCount(Vector target,List<Vector> hunters){return (int)hunters.stream().filter(h->flat(h,target)<=2.5&&h.z()-target.z()>=3).count();}
    public static Vector digStand(World w,Cell site,int floor,Vector away){if(w!=null){Vector best=null;List<Double> score=null;for(int radius:new int[]{1,2}){for(int dx=-radius;dx<=radius;dx++)for(int dy=-radius;dy<=radius;dy++){if(Math.max(Math.abs(dx),Math.abs(dy))!=radius)continue;int x=site.x()+dx,y=site.y()+dy;for(int z=Math.max(site.z()-1,0);z<Math.min(site.z()+5,240);z++){if(!w.solid(x,y,z))continue;if(z-site.z()<=3&&!w.solid(x,y,z-1)&&!w.solid(x,y,z-2)){double outward=away==null?0:-RecoveryPlanning.rounded(Math.hypot(x+.5-away.x(),y+.5-away.y()),1);var value=List.of((double)radius,(double)Math.abs(z-floor),outward,(double)(Math.abs(dx)+Math.abs(dy)));if(score==null||compare(value,score)<0){score=value;best=new Vector(x+.5,y+.5,z-2.25);}}break;}}if(best!=null)return best;}}return new Vector(site.x()+.5,site.y()+.5,floor-2.25);}
    static int compare(List<Double> a,List<Double> b){for(int i=0;i<a.size();i++){int c=Double.compare(a.get(i),b.get(i));if(c!=0)return c;}return 0;}
    public static List<Cell> tunnel(World w,Vector start,Vector target,double length){if(w==null)return List.of();double dx=target.x()-start.x(),dy=target.y()-start.y(),span=Math.hypot(dx,dy);if(span<1e-6)return List.of();int floor=floor(start),rise=target.z()<start.z()-1.5?1:0;var cells=new ArrayList<Cell>();for(double t=.75;t<=length;t+=.5){int x=(int)Math.floor(start.x()+dx/span*t),y=(int)Math.floor(start.y()+dy/span*t),lift=(int)Math.floor(t/2)*rise;for(int z:new int[]{floor-1-lift,floor-2-lift}){var c=new Cell(x,y,z);if(!cells.contains(c)&&z>=0&&z<239&&w.solid(c))cells.add(c);}}return List.copyOf(cells.subList(0,Math.min(8,cells.size())));}
    public record WallLine(int walls,int columns,double first){}
    public static WallLine wallLine(World w,Vector start,Vector target,double limit){if(w==null)return null;double dx=target.x()-start.x(),dy=target.y()-start.y(),span=Math.hypot(dx,dy);int floor=floor(start);if(span<1||span>limit||Math.abs(floor(target)-floor)>2)return null;int walls=0,columns=0;double first=-1;boolean wall=false;var seen=new ProjectSites.Column((int)Math.floor(start.x()),(int)Math.floor(start.y()));for(double t=.5;t<span-.5;){var col=new ProjectSites.Column((int)Math.floor(start.x()+dx/span*t),(int)Math.floor(start.y()+dy/span*t));t+=.5;if(col.equals(seen))continue;seen=col;int x=col.x(),y=col.y();if(x<0||x>=512||y<0||y>=512)return null;if(w.solid(x,y,floor-2)||w.solid(x,y,floor-1)&&w.solid(x,y,floor-3)){columns++;if(!wall){walls++;wall=true;if(first<0)first=t-.5;}continue;}wall=false;if(w.solid(x,y,floor-1))floor--;else if(!w.solid(x,y,floor)){boolean found=false;for(int drop=1;drop<=4;drop++)if(w.solid(x,y,floor+drop)){floor+=drop;found=true;break;}if(!found)return null;}}return new WallLine(walls,columns,first);}
    public Map<Integer,Integer> assign(List<Member> zombies,List<Target> survivors){owned();if(survivors.isEmpty()){targets.clear();return Map.of();}var alive=new HashMap<Integer,Target>();var load=new HashMap<Integer,Integer>();for(var s:survivors){alive.put(s.playerId(),s);load.put(s.playerId(),0);}for(var m:zombies)if(!m.bot()){var nearest=survivors.stream().min(Comparator.comparingDouble((Target s)->distance(m.position(),s.position())).thenComparingInt(Target::playerId)).orElseThrow();load.merge(nearest.playerId(),1,Integer::sum);}int cap=Math.max(1,(int)Math.ceil(zombies.size()/(double)survivors.size()))+1;var bots=zombies.stream().filter(Member::bot).sorted(Comparator.comparingDouble((Member m)->survivors.stream().mapToDouble(s->distance(m.position(),s.position())).min().orElseThrow()).thenComparingInt(Member::playerId)).toList();var result=new LinkedHashMap<Integer,Integer>();for(var m:bots){var best=survivors.stream().min(Comparator.comparingDouble((Target s)->cost(m,s,load,cap)).thenComparingInt(Target::playerId)).orElseThrow();var previous=targets.get(m.playerId());if(previous!=null&&alive.containsKey(previous)&&previous!=best.playerId()&&load.get(previous)<cap&&cost(m,alive.get(previous),load,cap)<=cost(m,best,load,cap)*1.3+8)best=alive.get(previous);result.put(m.playerId(),best.playerId());load.merge(best.playerId(),1,Integer::sum);}targets.clear();targets.putAll(result);return Collections.unmodifiableMap(result);}
    static double cost(Member m,Target s,Map<Integer,Integer> load,int cap){return distance(m.position(),s.position())*(1+.35*load.get(s.playerId()))+(load.get(s.playerId())>=cap?1000:0);}
    int observe(int id,Vector at,Vector goal,List<Object> key,double now,boolean working){double distance=distance(at,goal);var r=progress.get(id);if(r==null||!r.key.equals(key)){int level=r==null?0:r.level;progress.put(id,new Progress(key,distance,now,level,at));return level;}if(distance+1.5<=r.best){r.best=distance;r.at=r.closedAt=now;r.anchor=at;if(r.level>0&&now-r.levelSince>=8){r.level--;r.levelSince=now;}}else if(working&&now-r.closedAt<=8)r.at=now;else if(distance>3&&now-r.at>=5){if(BotVectors.distance(at,r.anchor)>4){r.at=now;r.anchor=at;r.best=distance;return r.level;}if(r.level<3){r.level++;stuckEvents++;}r.levelSince=r.at=r.closedAt=now;r.anchor=at;r.best=distance;}if(distance<=3){r.at=r.closedAt=now;r.best=Math.min(r.best,distance);}return r.level;}
    double stalled(Member m,Target t,double now){var r=progress.get(m.playerId());if(r==null||r.key.isEmpty()||!r.key.getFirst().equals(t.playerId())||distance(m.position(),r.anchor)>4)return 0;double idle=now-r.at;return idle>=1?idle:0;}
    private record Walk(double seconds,boolean bound){}
    Walk walk(Member m,Target t,Siege siege,double now){double flat=flat(m.position(),t.position()),climb=Math.max(0,m.position().z()-t.position().z());var approach=siege==null?null:siege.approach();boolean bound=false;double blocks;if(approach==null){if(siege!=null&&siege.isolated())return new Walk(Double.POSITIVE_INFINITY,false);blocks=flat+2*climb;}else{var moves=approach.movesFrom(m.position());if(moves!=null)blocks=Math.max(moves*.8,flat);else if(approach.closed())return new Walk(Double.POSITIVE_INFINITY,false);else{bound=true;blocks=Math.max(approach.frontier()*.8+Math.max(0,flat-approach.radius()),flat+2*climb);}}return new Walk(blocks/8+2*stalled(m,t,now),bound);}
    static double collapseSeconds(StructureCollapse.Plan plan,List<Member> group,World w){var cut=plan.cut().stream().filter(c->w==null||w.solid(c)).toList();if(cut.isEmpty())return 0;var sites=plan.sites().stream().filter(s->cut.stream().anyMatch(c->StructureCollapse.chebyshev(c,s)<=1)).toList();if(sites.isEmpty())sites=List.of(cut.getFirst());var diggers=group.stream().filter(Member::canDig).toList();if(diggers.isEmpty())return Double.POSITIVE_INFINITY;int crew=Math.min(diggers.size(),sites.size());var workSites=sites;var walks=diggers.stream().mapToDouble(m->workSites.stream().mapToDouble(s->distance(m.position(),SchematicPlanning.centre(s))).min().orElseThrow()).sorted().toArray();double hardness=Math.max(1,plan.cost()/(double)Math.max(1,plan.cut().size()));return walks[crew-1]/8+Math.ceil(sites.size()/(double)crew)*1.6*hardness;}
    public Map<Integer,Order> plan(List<Member> zombies,List<Target> survivors,Map<Integer,Siege> sieges,double now,World w){owned();var known=new HashSet<Integer>();for(var m:zombies)if(m.bot())known.add(m.playerId());for(var id:new ArrayList<>(progress.keySet()))if(!known.contains(id)){progress.remove(id);roles.remove(id);breaches.remove(id);vias.remove(id);}var assigned=assign(zombies,survivors);var byId=new HashMap<Integer,Target>();for(var s:survivors)byId.put(s.playerId(),s);besieged.keySet().removeIf(id->!byId.containsKey(id));var members=new HashMap<Integer,Member>();for(var m:zombies)members.put(m.playerId(),m);var groups=new TreeMap<Integer,List<Member>>();assigned.forEach((id,target)->groups.computeIfAbsent(target,k->new ArrayList<>()).add(members.get(id)));var orders=new LinkedHashMap<Integer,Order>();piles.clear();stuck.clear();for(var entry:groups.entrySet()){var target=byId.get(entry.getKey());var group=entry.getValue();group.sort(Comparator.comparingDouble((Member m)->distance(m.position(),target.position())).thenComparingInt(Member::playerId));var siege=sieges.get(target.playerId());if(siege!=null&&siege.position()!=null&&distance(siege.position(),target.position())>2.5)siege=null;var groupOrders=besiege(target,group,siege,w,now)?siegeOrders(target,group,siege,w):pursue(target,group,siege,w,now);int pile=pileCount(target.position(),group.stream().map(Member::position).toList());piles.put(target.playerId(),pile);maxPile=Math.max(maxPile,pile);for(var order:groupOrders){var member=members.get(order.zombieId());List<Object> key;Vector goal;if(Set.of("hunt","tunnel").contains(order.role())){key=List.of(order.targetId(),"hunt");goal=target.position();}else{key=Arrays.asList(order.targetId(),order.role(),order.aim(),List.of((int)order.goal().x(),(int)order.goal().y()));goal=order.goal();}int level=observe(member.playerId(),member.position(),goal,key,now,member.working());stuck.merge(target.playerId(),level,Math::max);order=escalate(order,member,target,level,w);if(order.role().equals("tunnel"))tunnelOrders++;roles.put(order.zombieId(),new Role(order.targetId(),order.role()));orders.put(order.zombieId(),order);}}return Collections.unmodifiableMap(orders);}
    boolean besiege(Target t,List<Member> group,Siege siege,World w,double now){int id=t.playerId();if(siege==null){besieged.remove(id);return false;}var approach=siege.approach();boolean isolated;if(approach!=null){isolated=approach.closed()&&group.stream().noneMatch(m->approach.movesFrom(m.position())!=null);if(isolated&&siege.floorZ()-approach.supportZ()<3){besieged.remove(id);return false;}}else isolated=siege.isolated();if(isolated){besieged.put(id,true);return true;}int support=approach==null?floor(t.position()):approach.supportZ();if(siege.plan()==null||siege.floorZ()-support<3){besieged.remove(id);return false;}double walk=group.stream().mapToDouble(m->walk(m,t,siege,now).seconds()).min().orElse(Double.POSITIVE_INFINITY),dig=collapseSeconds(siege.plan(),group,w);boolean chosen=besieged.getOrDefault(id,false)?dig<=walk+1:dig+1<walk;if(chosen){if(!besieged.getOrDefault(id,false))collapseChoices++;besieged.put(id,true);}else besieged.remove(id);return chosen;}
    List<Order> pursue(Target t,List<Member> group,Siege siege,World w,double now){var orders=new ArrayList<Order>();for(var m:group){var breach=breach(m,t,siege,w,now);if(breach!=null)orders.add(new Order(m.playerId(),t.playerId(),"tunnel",breach.position(),breach.cells(),breach.cells().isEmpty()?null:breach.cells().getFirst(),0));else{var via=via(m,t,siege,now);orders.add(new Order(m.playerId(),t.playerId(),"hunt",via==null?t.position():via,List.of(),null,0));}}return orders;}
    Vector via(Member m,Target t,Siege siege,double now){var a=siege==null?null:siege.approach();if(a==null)return null;var here=new ProjectSites.Column((int)Math.floor(m.position().x()),(int)Math.floor(m.position().y()));var cached=vias.get(m.playerId());boolean fresh=cached!=null&&cached.approach()==a&&now-cached.at()<.5;if(fresh&&cached.column().equals(here))return cached.point();Vector via=null;Cell entry=null,cell=a.cellAt(m.position());if(cell==null&&!a.closed()){entry=fresh?cached.entry():a.entryNear(m.position(),24);cell=entry;}if(cell!=null){int moves=a.steps().get(cell);double flat=flat(m.position(),t.position()),rise=m.position().z()-t.position().z();if(moves>10&&(moves*.8>flat+4||Math.abs(rise)>=2))via=SchematicPlanning.position(a.waypoint(cell,10));}vias.put(m.playerId(),new Via(fresh?cached.at():now,a,here,via,entry));return via;}
    Breach breach(Member m,Target t,Siege siege,World w,double now){if(w==null||!m.canDig())return null;double flat=flat(m.position(),t.position());if(flat>20){breaches.remove(m.playerId());return null;}var here=List.of((int)Math.floor(m.position().x()),(int)Math.floor(m.position().y()),(int)Math.floor(t.position().x()),(int)Math.floor(t.position().y()));var cached=breaches.get(m.playerId());if(cached!=null&&cached.target()==t.playerId()&&cached.column().equals(here)&&now-cached.at()<.5&&(cached.decision()==null||cached.decision().cells().stream().allMatch(w::solid)))return cached.decision();var decision=breachNow(m,t,siege,w,now,flat);breaches.put(m.playerId(),new BreachCache(now,t.playerId(),here,decision));return decision;}
    Breach breachNow(Member m,Target t,Siege siege,World w,double now,double flat){var line=wallLine(w,m.position(),t.position(),24);if(line==null||line.walls()==0)return null;double dig=flat/8+line.walls()*1.2+(line.columns()-line.walls())*.4;var walk=walk(m,t,siege,now);boolean clawing=new Role(t.playerId(),"tunnel").equals(roles.get(m.playerId()));double margin=walk.bound()?0:1;if(!(clawing&&m.working())&&!(clawing?dig<=walk.seconds()+1:dig+margin<=walk.seconds()))return null;if(!clawing)breachChoices++;var cells=tunnel(w,m.position(),t.position(),4);if(line.first()<=1.75)return new Breach(t.position(),cells);double back=line.first()-1;var face=new Vector(m.position().x()+(t.position().x()-m.position().x())/flat*back,m.position().y()+(t.position().y()-m.position().y())/flat*back,m.position().z());var spot=standNear(w,face,floor(m.position()),3);return new Breach(spot==null?t.position():spot,cells);}
    List<Order> siegeOrders(Target t,List<Member> group,Siege siege,World w){var orders=new ArrayList<Order>();var remaining=new ArrayList<>(group);var plan=siege.plan();if(plan!=null){var cut=plan.cut().stream().filter(c->w==null||w.solid(c)).toList();var sites=plan.sites().stream().filter(s->cut.stream().anyMatch(c->StructureCollapse.chebyshev(c,s)<=1)).toList();if(sites.isEmpty()&&!cut.isEmpty())sites=List.of(cut.getFirst());int per=remaining.size()>=2*sites.size()+2?2:1;var slots=new ArrayList<Cell>();for(var site:sites.subList(0,Math.min(6,sites.size())))for(int i=0;i<per;i++)slots.add(site);for(var site:slots){if(remaining.isEmpty())break;var m=remaining.stream().min(Comparator.comparingDouble((Member member)->distance(member.position(),SchematicPlanning.centre(site))).thenComparingInt(Member::playerId)).orElseThrow();remaining.remove(m);var cells=cut.stream().filter(c->StructureCollapse.chebyshev(c,site)<=1).sorted(SchematicPlanning.CELLS).toList();if(cells.isEmpty())cells=List.of(site);orders.add(new Order(m.playerId(),t.playerId(),"dig_root",digStand(w,site,siege.floorZ(),t.position()),cells,site,0));digOrders++;}}else{int crew=Math.min(4,Math.max(2,(int)Math.ceil(remaining.size()/3.)));var climbers=remaining.stream().filter(m->m.canDig()||m.canBuild()).limit(crew).toList();for(var m:climbers){remaining.remove(m);orders.add(new Order(m.playerId(),t.playerId(),"climb",t.position(),List.of(),null,0));climbOrders++;}}double radius=siege.approach()!=null&&siege.approach().closed()?Math.max(4,siege.approach().radius()+2):7;for(int i=0;i<remaining.size();i++){var m=remaining.get(i);var raw=ring(t.position(),i,Math.max(4,remaining.size()),radius+1.5*(i%2),siege.floorZ(),.6*t.playerId());var goal=standNear(w,raw,siege.floorZ(),3);orders.add(new Order(m.playerId(),t.playerId(),"surround",goal==null?raw:goal,List.of(),null,0));surroundOrders++;}return orders;}
    static Order withLevel(Order o,int level){return new Order(o.zombieId(),o.targetId(),o.role(),o.goal(),o.cells(),o.aim(),level);}
    Order escalate(Order order,Member m,Target target,int level,World w){if(level<=0)return order;if(Set.of("surround","dig_root").contains(order.role())){if(level>=2&&order.role().equals("dig_root")){var cells=tunnel(w,m.position(),order.goal(),3);if(!cells.isEmpty()){var combined=new ArrayList<>(cells);combined.addAll(order.cells());return new Order(order.zombieId(),order.targetId(),"tunnel",order.goal(),combined,order.aim(),level);}}return withLevel(order,level);}if(order.role().equals("tunnel")&&(level<2||m.working()))return withLevel(order,level);boolean near=flat(m.position(),target.position())<=20;var cells=near&&level>=2&&!order.role().equals("tunnel")?tunnel(w,m.position(),target.position(),4):List.<Cell>of();if(!cells.isEmpty()&&m.canDig())return new Order(order.zombieId(),order.targetId(),"tunnel",target.position(),cells,cells.getFirst(),level);boolean above=m.position().z()-target.position().z()>=2;if(level>=2&&near&&above&&(m.canDig()||m.canBuild()))return new Order(order.zombieId(),order.targetId(),"climb",target.position(),List.of(),null,level);int floor=floor(target.position());var goal=standNear(w,ring(target.position(),m.playerId()+level,4,9,floor,Math.PI/4),floor,3);return goal==null?withLevel(order,level):new Order(order.zombieId(),order.targetId(),"flank",goal,List.of(),null,level);}
}
